import re
from .exceptions import BaseConfigInputInvalid, AttributeNotFound


class BaseConfig:

    def __init__(self, input_dict):
        if not isinstance(input_dict, dict):
            raise BaseConfigInputInvalid

        self.__dict__ = self._convert_elements(input_dict)

    def _convert_elements(self, input_data):
        if isinstance(input_data, dict):
            for name, elem_data in input_data.items():
                if isinstance(elem_data, dict):
                    input_data[name] = BaseConfig(elem_data)
                elif isinstance(elem_data, list):
                    input_data[name] = [BaseConfig(sub_elem) if isinstance(sub_elem, dict) else
                                        self._convert_elements(sub_elem) for sub_elem in elem_data]
                else:
                    input_data[name] = elem_data
        elif isinstance(input_data, list):
            input_data = [self._convert_elements(elem_data) for elem_data in input_data]
        return input_data

    def __iter__(self):
        for key in self.__dict__:
            yield key

    def __getitem__(self, index_path):
        first_index, left_path = self._get_first_index(index_path)
        if first_index not in self.__dict__:
            raise AttributeNotFound(index_path)

        return self.__dict__[first_index][left_path] if left_path else self.__dict__[first_index]

    @staticmethod
    def _get_first_index(index_path):
        res = re.match("(\/{0,1})(?P<first_indx>[^\/]+)(\/{0,1})(?P<left_path>.*)", index_path)  # noqa: W605
        if res:
            res_dict = res.groupdict()
            return res_dict['first_indx'], res_dict['left_path']
        raise AttributeNotFound(index_path)

    def __setitem__(self, index_path, value):
        first_index, left_path = self._get_first_index(index_path)
        if first_index not in self.__dict__:
            raise AttributeNotFound(index_path)

        if left_path:
            self.__dict__[first_index][left_path] = value
        else:
            self.__dict__[first_index] = value

    def __delitem__(self, index_path):
        first_index, left_path = self._get_first_index(index_path)
        if first_index not in self.__dict__:
            raise AttributeNotFound(index_path)

        if left_path:
            del self.__dict__[first_index][left_path]
        else:
            del self.__dict__[first_index]

    def keys(self):
        return self.__dict__.keys()

    def items(self):
        return self.__dict__.items()

    def get(self, attr_name, defaut=None):
        return self.__dict__[attr_name] if attr_name in self.__dict__ else defaut

    def get_entity_path_list(self, entity_name):
        return ['/'.join(path_index) for path_index in self._find_entity_idx_list(entity_name)]

    def _find_entity_idx_list(self, entity_name):
        if entity_name in self.__dict__:
            return [[entity_name]]
        else:
            all_idx_list = []
            for name, elem_data in self.items():
                if isinstance(elem_data, BaseConfig):
                    sub_path_list = elem_data._find_entity_idx_list(entity_name)
                    if sub_path_list:
                        all_idx_list += [[name] + sub_path for sub_path in sub_path_list]
            return all_idx_list

    def __str__(self):
        display_str = '{\n'
        for key, elem in self.__dict__.items():
            if isinstance(elem, BaseConfig):
                display_str += "{\n"
                display_str += f'{key}:\n'
                display_str += str(elem)
                display_str += "}\n"
            elif isinstance(elem, list):
                display_str += "["
                for idx, sub_elem in enumerate(elem):
                    if isinstance(sub_elem, BaseConfig):
                        display_str += f'{idx}:\n'
                        display_str += str(elem)
                    else:
                        display_str += f'{sub_elem},\n'
                display_str += "]\n"
            else:
                display_str += f"{key}: {elem}\n"
        display_str += '}\n'
        return display_str
